<div class="patient-page-heading"><div><span class="eyebrow text-secondary">CUENTA</span><h1><?= $escape($account['nombre_usuario']) ?></h1><p class="text-secondary mb-0">Detalle administrativo y permisos efectivos.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="/usuarios">Volver</a><a class="btn btn-clinic" href="/usuarios/editar?id=<?= $escape($account['id_usuario']) ?>">Editar</a></div></div>
<section class="patient-card patient-detail-section"><h2 class="h5">Datos administrativos</h2><dl class="row g-3"><dt class="col-sm-3">Nombre de usuario</dt><dd class="col-sm-9"><?= $escape($account['nombre_usuario']) ?></dd><dt class="col-sm-3">Correo de acceso</dt><dd class="col-sm-9"><?= $escape($account['correo_acceso']) ?></dd><dt class="col-sm-3">Rol</dt><dd class="col-sm-9"><?= $escape($account['rol']) ?></dd><dt class="col-sm-3">Estado</dt><dd class="col-sm-9"><?= $escape(ucfirst($account['estado'])) ?></dd><dt class="col-sm-3">Perfil relacionado</dt><dd class="col-sm-9"><?php if($account['id_paciente']!==null): ?>Paciente: <?= $escape($account['paciente_nombres'].' '.$account['paciente_apellidos']) ?><?php elseif($account['id_medico']!==null): ?>Médico: <?= $escape($account['medico_nombres'].' '.$account['medico_apellidos']) ?><?php else: ?>Sin perfil de paciente o médico vinculado<?php endif; ?></dd><dt class="col-sm-3">Creada</dt><dd class="col-sm-9"><?= $escape($account['created_at']) ?></dd><dt class="col-sm-3">Última actualización</dt><dd class="col-sm-9"><?= $escape($account['updated_at']) ?></dd></dl></section>
<section class="patient-card patient-detail-section"><h2 class="h5">Permisos efectivos de <?= $escape($account['rol']) ?></h2><ul class="permission-list"><?php foreach($permissions as $permission): ?><li><?= $escape($permission['name']) ?><?php if($permission['description']): ?><small class="d-block text-secondary"><?= $escape($permission['description']) ?></small><?php endif; ?></li><?php endforeach; ?></ul></section>
